classify <- function(n) {
  if (n == 0) {
    "zero"
  } else if (n == 1) {
    "one"
  } else if (n == 2) {
    "two"
  } else if (n == 3) {
    "three"
  } else if (n == 4) {
    "four"
  } else if (n == 5) {
    "five"
  } else if (n == 6) {
    "six"
  } else if (n == 7) {
    "seven"
  } else if (n == 8) {
    "eight"
  } else {
    "other"
  }
}
